{"path": "bowling.py", "content": "class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 1          # current frame number (1-10)
        self.frame_rolls = []   # rolls made in the current frame

    def _game_over(self):
        if self.frame < 10:
            return False
        tenth = self.frame_rolls
        if len(tenth) == 3:
            return True
        return len(tenth) == 2 and tenth[0] + tenth[1] < 10

    def roll(self, pins):
        if self._game_over():
            raise IndexError("cannot roll after the game is over")
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("negative roll is invalid")
        if pins > 10:
            raise ValueError("pin count exceeds pins on the lane")

        current = self.frame_rolls
        if self.frame < 10:
            if current and current[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
            current.append(pins)
            if pins == 10 or len(current) == 2:
                self.frame += 1
                self.frame_rolls = []
        else:
            if len(current) == 1 and current[0] < 10 and current[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
            if (len(current) == 2 and current[0] == 10 and current[1] < 10
                    and current[1] + pins > 10):
                raise ValueError("invalid fill balls")
            current.append(pins)
        self.rolls.append(pins)

    def score(self):
        if not self._game_over():
            raise IndexError("score cannot be taken until the end of the game")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
